let lrgrep_execute_nearest_opener 
  (_lrgrep_env : _ Parser_raw.MenhirInterpreter.env)
  (((token : Parser_raw.MenhirInterpreter.token), (_startpos_token_ : Lexing.position), (_endpos_token_ : Lexing.position)) as _lrgrep_lookahead)
  =
  let _ = _lrgrep_lookahead in
fun (__clause, (__registers : Parser_raw.MenhirInterpreter.element Lrgrep_runtime.register_values), (__depths : int array))
  : _ option ->
  match __clause, token with
  | 0, (RPAREN|RBRACKET|RBRACE|GREATERRBRACE|END|DONE|BARRBRACKET) ->
    let o0, _startpos_o0_, _endpos_o0_, _positions_o0_ = match __registers.(0) with 
      | Empty -> (None, None, None, None)
      | Location _ -> assert false
      | Value (Parser_raw.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser_raw.MenhirInterpreter.incoming_symbol st with
          | T T_LPAREN -> (x : unit)
          | _ -> assert false
        in
        (Some (x), Some (startp), Some (endp), Some ((startp, endp)))
    in
    let _ = o0 in
    let o1, _startpos_o1_, _endpos_o1_, _positions_o1_ = match __registers.(1) with 
      | Empty -> (None, None, None, None)
      | Location _ -> assert false
      | Value (Parser_raw.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser_raw.MenhirInterpreter.incoming_symbol st with
          | T T_LBRACKET -> (x : unit)
          | _ -> assert false
        in
        (Some (x), Some (startp), Some (endp), Some ((startp, endp)))
    in
    let _ = o1 in
    let o2, _startpos_o2_, _endpos_o2_, _positions_o2_ = match __registers.(2) with 
      | Empty -> (None, None, None, None)
      | Location _ -> assert false
      | Value (Parser_raw.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser_raw.MenhirInterpreter.incoming_symbol st with
          | T T_LBRACKETLESS -> (x : unit)
          | _ -> assert false
        in
        (Some (x), Some (startp), Some (endp), Some ((startp, endp)))
    in
    let _ = o2 in
    let o3, _startpos_o3_, _endpos_o3_, _positions_o3_ = match __registers.(3) with 
      | Empty -> (None, None, None, None)
      | Location _ -> assert false
      | Value (Parser_raw.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser_raw.MenhirInterpreter.incoming_symbol st with
          | T T_LBRACKETGREATER -> (x : unit)
