let lrgrep_reduce env ~start ~depth ~targets reduction =
  let module I = Parser_raw.MenhirInterpreter in
  let rec pop_n env n =
    if n = 0 then env else
      match I.pop env with
      | Some env -> pop_n env (n - 1)
      | None -> raise Lrgrep_runtime.Unavailable_value
  in
  if start < 0 then raise Lrgrep_runtime.Unavailable_value;
  let env = pop_n env start in
  let base = pop_n env (depth - start) in
  let rec go env =
    match reduction (I.current_state_number env) with
    | 0 -> raise Lrgrep_runtime.Unavailable_value
    | prod ->
      let env =
        try I.force_reduction (I.find_production (prod - 1)) env
        with Invalid_argument _ -> raise Lrgrep_runtime.Unavailable_value
      in
      match I.pop env, I.top env with
      | Some below, Some x
        when I.equal below base &&
             List.mem (I.current_state_number env) targets -> x
      | _ -> go env
  in
  go env

